// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ConsentListCollectionPoints Collection points (CON-09)
	// (GET /admin/v1/consent/collection-points)
	ConsentListCollectionPoints(ctx context.Context, request ConsentListCollectionPointsRequestObject) (ConsentListCollectionPointsResponseObject, error)
	// ConsentCreateCollectionPoint Create a draft collection point
	// (POST /admin/v1/consent/collection-points)
	ConsentCreateCollectionPoint(ctx context.Context, request ConsentCreateCollectionPointRequestObject) (ConsentCreateCollectionPointResponseObject, error)
	// ConsentGetCollectionPoint A collection point with its purposes
	// (GET /admin/v1/consent/collection-points/{id})
	ConsentGetCollectionPoint(ctx context.Context, request ConsentGetCollectionPointRequestObject) (ConsentGetCollectionPointResponseObject, error)
	// ConsentUpdateCollectionPoint Save a collection point (If-Match); a live one must still pass the publish checks
	// (PUT /admin/v1/consent/collection-points/{id})
	ConsentUpdateCollectionPoint(ctx context.Context, request ConsentUpdateCollectionPointRequestObject) (ConsentUpdateCollectionPointResponseObject, error)
	// ConsentPublishCollectionPoint Publish after the s.19 / s.26 checks; issues the public key used by links, QR codes and forms
	// (POST /admin/v1/consent/collection-points/{id}/publish)
	ConsentPublishCollectionPoint(ctx context.Context, request ConsentPublishCollectionPointRequestObject) (ConsentPublishCollectionPointResponseObject, error)
	// ConsentRetireCollectionPoint Retire a collection point; its public key stops working
	// (POST /admin/v1/consent/collection-points/{id}/retire)
	ConsentRetireCollectionPoint(ctx context.Context, request ConsentRetireCollectionPointRequestObject) (ConsentRetireCollectionPointResponseObject, error)
	// ConsentListPurposes Purposes with their live version (CON-12)
	// (GET /admin/v1/consent/purposes)
	ConsentListPurposes(ctx context.Context, request ConsentListPurposesRequestObject) (ConsentListPurposesResponseObject, error)
	// ConsentCreatePurpose Create a purpose with its first draft; it goes live once a DPO approves and it is published (PLT-08)
	// (POST /admin/v1/consent/purposes)
	ConsentCreatePurpose(ctx context.Context, request ConsentCreatePurposeRequestObject) (ConsentCreatePurposeResponseObject, error)
	// ConsentGetPurpose A purpose with its published versions
	// (GET /admin/v1/consent/purposes/{id})
	ConsentGetPurpose(ctx context.Context, request ConsentGetPurposeRequestObject) (ConsentGetPurposeResponseObject, error)
	// ConsentSavePurposeDraft Save the draft of the next version (then submit it for approval through the record-versions endpoints)
	// (PUT /admin/v1/consent/purposes/{id}/draft)
	ConsentSavePurposeDraft(ctx context.Context, request ConsentSavePurposeDraftRequestObject) (ConsentSavePurposeDraftResponseObject, error)
	// ConsentRetirePurpose Take a purpose out of use (refused while an active collection point shows it)
	// (POST /admin/v1/consent/purposes/{id}/retire)
	ConsentRetirePurpose(ctx context.Context, request ConsentRetirePurposeRequestObject) (ConsentRetirePurposeResponseObject, error)
	// ConsentRecordOnBehalf Record decisions for a data subject as staff (counter, call centre) — including withdrawal with a reason (CON-13)
	// (POST /admin/v1/consent/records)
	ConsentRecordOnBehalf(ctx context.Context, request ConsentRecordOnBehalfRequestObject) (ConsentRecordOnBehalfResponseObject, error)
	// ConsentGetSettings Where consent data is stored and how identifiers are protected (CON-17)
	// (GET /admin/v1/consent/settings)
	ConsentGetSettings(ctx context.Context, request ConsentGetSettingsRequestObject) (ConsentGetSettingsResponseObject, error)
	// ConsentListSubjects Most recently active data subjects (identifiers masked)
	// (GET /admin/v1/consent/subjects)
	ConsentListSubjects(ctx context.Context, request ConsentListSubjectsRequestObject) (ConsentListSubjectsResponseObject, error)
	// ConsentSearchSubjects Find the data subject an identifier belongs to (exact match by blind index; POST keeps the identifier out of URLs)
	// (POST /admin/v1/consent/subjects/search)
	ConsentSearchSubjects(ctx context.Context, request ConsentSearchSubjectsRequestObject) (ConsentSearchSubjectsResponseObject, error)
	// ConsentGetSubject A data subject profile: status per purpose and full history (CON-15)
	// (GET /admin/v1/consent/subjects/{id})
	ConsentGetSubject(ctx context.Context, request ConsentGetSubjectRequestObject) (ConsentGetSubjectResponseObject, error)
	// ConsentVerifySubject Recompute the subject's receipt chain and report the first receipt that doesn't match
	// (POST /admin/v1/consent/subjects/{id}/verify)
	ConsentVerifySubject(ctx context.Context, request ConsentVerifySubjectRequestObject) (ConsentVerifySubjectResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

